import type * as THREE from 'three';
import type { Quat, Vec3 } from '../contracts/math';

/** One box-shaped piece of an obstacle: a mesh plus the collider it generates. */
export interface ObstaclePart {
  id: string;
  geometry: THREE.BufferGeometry;
  material: THREE.Material;
  /** Half extents of the box collider generated for this piece. */
  halfExtents: Vec3;
  /** Offset relative to the group the part is mounted on. */
  offset?: Vec3;
  /** Local rotation relative to the group the part is mounted on. */
  rotation?: Quat;
  /** Set to false for decorative pieces that must not collide. */
  collider?: boolean;
  friction?: number;
  restitution?: number;
}

export interface ObstacleColliderSpec {
  id: string;
  halfExtents: Vec3;
  offset: Vec3;
  rotation: Quat;
  friction: number;
  restitution: number;
}

export interface ObstacleBodySpec {
  id: string;
  kind: 'kinematic' | 'fixed';
  position: Vec3;
  rotation: Quat;
  colliders: readonly ObstacleColliderSpec[];
}

/** Handle to the physics body an obstacle owns. */
export interface ObstacleBodyHandle {
  setNextRotation(rotation: Quat): void;
  dispose(): void;
}

/**
 * Physics is injected so obstacles can be unit tested without booting the
 * Rapier wasm module. RapierObstaclePhysics is the production implementation.
 */
export interface ObstaclePhysicsAdapter {
  createBody(spec: ObstacleBodySpec): ObstacleBodyHandle;
}

export interface RotatingObstacleConfig {
  id: string;
  position: Vec3;
  /** World-space rotation axis, defaults to +Y. */
  axis?: Vec3;
  /** Radians per second, negative values spin the other way. */
  speed?: number;
  /** Initial angle in radians. */
  phase?: number;
  enabled?: boolean;
  friction?: number;
  restitution?: number;
  color?: number;
  scene?: THREE.Object3D;
  physics?: ObstaclePhysicsAdapter;
  /** Longest simulated step, keeps a stalled frame from teleporting the obstacle. */
  maxStepSeconds?: number;
}
