import type { Quat, Vec3 } from '../contracts/math';
import { requireFinite } from './validation';

export const TAU = Math.PI * 2;
export const IDENTITY_QUAT: Quat = { x: 0, y: 0, z: 0, w: 1 };
export const UP_AXIS: Vec3 = { x: 0, y: 1, z: 0 };
export const DEFAULT_MAX_STEP_SECONDS = 0.1;

const EPSILON = 1e-8;

/** Normalises any angle into [0, TAU). Non-finite input collapses to 0. */
export function wrapAngle(angle: number): number {
  if (!Number.isFinite(angle)) return 0;
  const wrapped = angle % TAU;
  return wrapped < 0 ? wrapped + TAU : wrapped;
}

export function crossProduct(a: Vec3, b: Vec3): Vec3 {
  return {
    x: a.y * b.z - a.z * b.y,
    y: a.z * b.x - a.x * b.z,
    z: a.x * b.y - a.y * b.x,
  };
}

export function normalizeAxis(axis: Vec3): Vec3 {
  const length = Math.hypot(axis.x, axis.y, axis.z);
  if (!Number.isFinite(length) || length < 1e-6) {
    throw new Error('Rotation axis must be a finite, non-zero vector');
  }
  return { x: axis.x / length, y: axis.y / length, z: axis.z / length };
}

export function normalizeQuaternion(q: Quat): Quat {
  const length = Math.hypot(q.x, q.y, q.z, q.w);
  if (length < EPSILON) return { ...IDENTITY_QUAT };
  return { x: q.x / length, y: q.y / length, z: q.z / length, w: q.w / length };
}

export function quaternionFromAxisAngle(axis: Vec3, angle: number): Quat {
  const unit = normalizeAxis(axis);
  const half = requireFinite(angle, 'rotation angle') / 2;
  const sin = Math.sin(half);
  return { x: unit.x * sin, y: unit.y * sin, z: unit.z * sin, w: Math.cos(half) };
}

/** Quaternion product a * b: b is applied first, then a. */
export function multiplyQuaternions(a: Quat, b: Quat): Quat {
  return {
    x: a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
    y: a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
    z: a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
    w: a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
  };
}

/** Shortest rotation that maps one direction onto another. */
export function quaternionFromUnitVectors(from: Vec3, to: Vec3): Quat {
  const a = normalizeAxis(from);
  const b = normalizeAxis(to);
  const dot = a.x * b.x + a.y * b.y + a.z * b.z;
  if (dot > 1 - 1e-9) return { ...IDENTITY_QUAT };
  if (dot < -1 + 1e-9) {
    const reference = Math.abs(a.x) < 0.9 ? { x: 1, y: 0, z: 0 } : { x: 0, y: 0, z: 1 };
    return quaternionFromAxisAngle(crossProduct(a, reference), Math.PI);
  }
  const axis = crossProduct(a, b);
  return normalizeQuaternion({ x: axis.x, y: axis.y, z: axis.z, w: 1 + dot });
}

export function rotateVector(q: Quat, v: Vec3): Vec3 {
  const u = { x: q.x, y: q.y, z: q.z };
  const first = crossProduct(u, v);
  const t = { x: first.x + q.w * v.x, y: first.y + q.w * v.y, z: first.z + q.w * v.z };
  const second = crossProduct(u, t);
  return { x: v.x + 2 * second.x, y: v.y + 2 * second.y, z: v.z + 2 * second.z };
}

export interface RotationDriverOptions {
  speed: number;
  phase?: number;
  maxStepSeconds?: number;
}

/**
 * Time source for rotating obstacles. The angle is a pure function of the
 * accumulated time, so replaying the same step sequence always reproduces the
 * same orientation. Long frames are clamped instead of teleporting the piece
 * through the ball.
 */
export class RotationDriver {
  readonly speed: number;
  readonly phase: number;
  readonly maxStepSeconds: number;

  private elapsedSeconds = 0;

  constructor(options: RotationDriverOptions) {
    this.speed = requireFinite(options.speed, 'rotation speed');
    this.phase = wrapAngle(requireFinite(options.phase ?? 0, 'rotation phase'));
    const maxStep = options.maxStepSeconds ?? DEFAULT_MAX_STEP_SECONDS;
    this.maxStepSeconds = Number.isFinite(maxStep) && maxStep > 0 ? maxStep : DEFAULT_MAX_STEP_SECONDS;
  }

  get elapsed(): number {
    return this.elapsedSeconds;
  }

  get angle(): number {
    return wrapAngle(this.phase + this.speed * this.elapsedSeconds);
  }

  advance(deltaSeconds: number): number {
    if (Number.isFinite(deltaSeconds) && deltaSeconds > 0) {
      this.elapsedSeconds += Math.min(deltaSeconds, this.maxStepSeconds);
    }
    return this.angle;
  }

  setElapsed(seconds: number): number {
    this.elapsedSeconds = Number.isFinite(seconds) && seconds > 0 ? seconds : 0;
    return this.angle;
  }

  reset(): void {
    this.elapsedSeconds = 0;
  }
}
