import * as THREE from 'three';
import type { Quat, Vec3 } from '../contracts/math';
import {
  IDENTITY_QUAT,
  RotationDriver,
  UP_AXIS,
  multiplyQuaternions,
  normalizeAxis,
  quaternionFromAxisAngle,
  quaternionFromUnitVectors,
} from './rotation';
import type {
  ObstacleBodyHandle,
  ObstacleColliderSpec,
  ObstaclePart,
  RotatingObstacleConfig,
} from './types';
import { requireFinite, requireId, requireVec3 } from './validation';

const DEFAULT_FRICTION = 0.4;
const DEFAULT_RESTITUTION = 0.55;
const DEFAULT_SPEED = 1;

export interface RotatingObstacleParts {
  /** Pieces mounted on the spinning pivot. */
  rotating: readonly ObstaclePart[];
  /** Pieces that stay put, e.g. a windmill tower. */
  fixed?: readonly ObstaclePart[];
}

/**
 * Shared lifecycle for every rotating course obstacle: build the visual
 * hierarchy, publish box colliders to physics, spin deterministically and
 * release every resource exactly once.
 *
 * Parts are authored with the spin axis pointing along local +Y; the obstacle
 * aligns that axis with the configured world axis, so the same geometry works
 * for a ground spinner and a vertical windmill wheel.
 */
export class RotatingObstacle {
  readonly id: string;
  readonly position: Vec3;
  readonly axis: Vec3;
  readonly root: THREE.Group;
  readonly pivot: THREE.Group;
  readonly colliders: readonly ObstacleColliderSpec[];
  readonly staticColliders: readonly ObstacleColliderSpec[];

  private readonly driver: RotationDriver;
  private readonly alignment: Quat;
  private readonly bodies: ObstacleBodyHandle[] = [];
  private readonly geometries = new Set<THREE.BufferGeometry>();
  private readonly materials = new Set<THREE.Material>();
  private rotatingBody: ObstacleBodyHandle | null = null;
  private enabledFlag: boolean;
  private disposed = false;

  constructor(config: RotatingObstacleConfig, parts: RotatingObstacleParts) {
    this.id = requireId(config.id, 'RotatingObstacle');
    this.position = requireVec3(config.position, this.id + ' position');
    this.axis = normalizeAxis(config.axis ?? UP_AXIS);
    this.driver = new RotationDriver({
      speed: requireFinite(config.speed ?? DEFAULT_SPEED, this.id + ' speed'),
      phase: requireFinite(config.phase ?? 0, this.id + ' phase'),
      maxStepSeconds: config.maxStepSeconds,
    });
    this.alignment = quaternionFromUnitVectors(UP_AXIS, this.axis);
    this.enabledFlag = config.enabled ?? true;

    this.root = new THREE.Group();
    this.root.name = 'obstacle:' + this.id;
    this.root.position.set(this.position.x, this.position.y, this.position.z);
    this.pivot = new THREE.Group();
    this.pivot.name = 'obstacle:' + this.id + ':pivot';
    this.root.add(this.pivot);

    const friction = config.friction ?? DEFAULT_FRICTION;
    const restitution = config.restitution ?? DEFAULT_RESTITUTION;
    this.colliders = this.mount(this.pivot, parts.rotating, friction, restitution);
    this.staticColliders = this.mount(this.root, parts.fixed ?? [], friction, restitution);
    this.applyRotation();

    config.scene?.add(this.root);

    const physics = config.physics;
    if (!physics) return;
    if (this.colliders.length > 0) {
      this.rotatingBody = physics.createBody({
        id: this.id,
        kind: 'kinematic',
        position: this.position,
        rotation: this.rotation,
        colliders: this.colliders,
      });
      this.bodies.push(this.rotatingBody);
    }
    if (this.staticColliders.length > 0) {
      this.bodies.push(physics.createBody({
        id: this.id + ':static',
        kind: 'fixed',
        position: this.position,
        rotation: { ...IDENTITY_QUAT },
        colliders: this.staticColliders,
      }));
    }
  }

  get angle(): number {
    return this.driver.angle;
  }

  get elapsed(): number {
    return this.driver.elapsed;
  }

  get speed(): number {
    return this.driver.speed;
  }

  get enabled(): boolean {
    return this.enabledFlag;
  }

  set enabled(value: boolean) {
    this.enabledFlag = value;
  }

  get isDisposed(): boolean {
    return this.disposed;
  }

  /** Spin around the local axis, before world alignment. */
  get spin(): Quat {
    return quaternionFromAxisAngle(UP_AXIS, this.angle);
  }

  /** World rotation of the spinning pivot. */
  get rotation(): Quat {
    return multiplyQuaternions(this.alignment, this.spin);
  }

  update(deltaSeconds: number): void {
    if (this.disposed || !this.enabledFlag) return;
    const before = this.driver.elapsed;
    this.driver.advance(deltaSeconds);
    if (this.driver.elapsed === before) return;
    this.applyRotation();
  }

  /** Jump to an absolute point on the rotation timeline (replays, tests). */
  setElapsed(seconds: number): void {
    if (this.disposed) return;
    this.driver.setElapsed(seconds);
    this.applyRotation();
  }

  reset(): void {
    if (this.disposed) return;
    this.driver.reset();
    this.applyRotation();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.root.removeFromParent();
    this.pivot.clear();
    this.root.clear();
    for (const geometry of this.geometries) geometry.dispose();
    for (const material of this.materials) material.dispose();
    this.geometries.clear();
    this.materials.clear();
    for (const body of this.bodies) body.dispose();
    this.bodies.length = 0;
    this.rotatingBody = null;
  }

  private mount(
    parent: THREE.Object3D,
    parts: readonly ObstaclePart[],
    friction: number,
    restitution: number,
  ): ObstacleColliderSpec[] {
    const specs: ObstacleColliderSpec[] = [];
    for (const part of parts) {
      const offset = part.offset ?? { x: 0, y: 0, z: 0 };
      const rotation = part.rotation ?? { ...IDENTITY_QUAT };
      const mesh = new THREE.Mesh(part.geometry, part.material);
      mesh.name = this.id + ':' + part.id;
      mesh.position.set(offset.x, offset.y, offset.z);
      mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      this.geometries.add(part.geometry);
      this.materials.add(part.material);
      if (part.collider === false) continue;
      specs.push({
        id: mesh.name,
        halfExtents: requireVec3(part.halfExtents, mesh.name + ' halfExtents'),
        offset: requireVec3(offset, mesh.name + ' offset'),
        rotation,
        friction: part.friction ?? friction,
        restitution: part.restitution ?? restitution,
      });
    }
    return specs;
  }

  private applyRotation(): void {
    const rotation = this.rotation;
    this.pivot.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
    this.rotatingBody?.setNextRotation(rotation);
  }
}
