import * as THREE from 'three';
import { RotatingObstacle } from './RotatingObstacle';
import type { ObstaclePart, RotatingObstacleConfig } from './types';
import { requirePositive } from './validation';

export interface RotatingBarOptions extends RotatingObstacleConfig {
  /** Full length of the bar, centred on the pivot. */
  length?: number;
  thickness?: number;
  height?: number;
}

const DEFAULT_LENGTH = 4;
const DEFAULT_THICKNESS = 0.35;
const DEFAULT_HEIGHT = 0.5;
const DEFAULT_COLOR = 0xd8dee9;

interface BarSpec {
  part: ObstaclePart;
  length: number;
  thickness: number;
  height: number;
}

function resolveBar(options: RotatingBarOptions): BarSpec {
  const length = requirePositive(options.length ?? DEFAULT_LENGTH, 'RotatingBar length');
  const thickness = requirePositive(options.thickness ?? DEFAULT_THICKNESS, 'RotatingBar thickness');
  const height = requirePositive(options.height ?? DEFAULT_HEIGHT, 'RotatingBar height');
  return {
    length,
    thickness,
    height,
    part: {
      id: 'bar',
      geometry: new THREE.BoxGeometry(length, height, thickness),
      material: new THREE.MeshStandardMaterial({
        color: options.color ?? DEFAULT_COLOR,
        roughness: 0.5,
        metalness: 0.2,
      }),
      halfExtents: { x: length / 2, y: height / 2, z: thickness / 2 },
    },
  };
}

/** Single sweeping bar: the simplest rotating obstacle, long along local +X. */
export class RotatingBar extends RotatingObstacle {
  readonly length: number;
  readonly thickness: number;
  readonly height: number;

  constructor(options: RotatingBarOptions) {
    const spec = resolveBar(options);
    super(options, { rotating: [spec.part] });
    this.length = spec.length;
    this.thickness = spec.thickness;
    this.height = spec.height;
  }
}
