import * as THREE from 'three';
import { RotatingObstacle } from './RotatingObstacle';
import { TAU, UP_AXIS, quaternionFromAxisAngle } from './rotation';
import type { ObstaclePart, RotatingObstacleConfig } from './types';
import { requireCount, requirePositive } from './validation';

export interface SpinnerOptions extends RotatingObstacleConfig {
  armCount?: number;
  /** Length of a single arm measured from the hub outwards. */
  armLength?: number;
  thickness?: number;
  height?: number;
  hubRadius?: number;
}

const DEFAULT_ARM_COUNT = 4;
const DEFAULT_ARM_LENGTH = 2.4;
const DEFAULT_THICKNESS = 0.3;
const DEFAULT_HEIGHT = 0.45;
const DEFAULT_COLOR = 0x58d0c4;

interface SpinnerSpec {
  parts: ObstaclePart[];
  armCount: number;
  armLength: number;
  thickness: number;
  height: number;
  hubRadius: number;
}

function resolveSpinner(options: SpinnerOptions): SpinnerSpec {
  const armCount = requireCount(options.armCount ?? DEFAULT_ARM_COUNT, 'Spinner armCount');
  const armLength = requirePositive(options.armLength ?? DEFAULT_ARM_LENGTH, 'Spinner armLength');
  const thickness = requirePositive(options.thickness ?? DEFAULT_THICKNESS, 'Spinner thickness');
  const height = requirePositive(options.height ?? DEFAULT_HEIGHT, 'Spinner height');
  const hubRadius = requirePositive(options.hubRadius ?? thickness, 'Spinner hubRadius');
  const material = new THREE.MeshStandardMaterial({
    color: options.color ?? DEFAULT_COLOR,
    roughness: 0.45,
    metalness: 0.25,
  });
  const armGeometry = new THREE.BoxGeometry(armLength, height, thickness);
  const parts: ObstaclePart[] = [{
    id: 'hub',
    geometry: new THREE.CylinderGeometry(hubRadius, hubRadius, height * 1.1, 12),
    material,
    halfExtents: { x: hubRadius, y: height * 0.55, z: hubRadius },
    collider: false,
  }];

  for (let index = 0; index < armCount; index += 1) {
    const angle = (TAU * index) / armCount;
    parts.push({
      id: 'arm-' + index,
      geometry: armGeometry,
      material,
      halfExtents: { x: armLength / 2, y: height / 2, z: thickness / 2 },
      offset: {
        x: Math.cos(angle) * (armLength / 2),
        y: 0,
        z: -Math.sin(angle) * (armLength / 2),
      },
      rotation: quaternionFromAxisAngle(UP_AXIS, angle),
    });
  }

  return { parts, armCount, armLength, thickness, height, hubRadius };
}

/** Radial fan of arms around a hub; two arms give a classic sweeping bar. */
export class Spinner extends RotatingObstacle {
  readonly armCount: number;
  readonly armLength: number;
  readonly thickness: number;
  readonly height: number;
  readonly hubRadius: number;

  constructor(options: SpinnerOptions) {
    const spec = resolveSpinner(options);
    super(options, { rotating: spec.parts });
    this.armCount = spec.armCount;
    this.armLength = spec.armLength;
    this.thickness = spec.thickness;
    this.height = spec.height;
    this.hubRadius = spec.hubRadius;
  }
}
