import * as THREE from 'three';
import type { Vec3 } from '../contracts/math';
import { RotatingObstacle } from './RotatingObstacle';
import { TAU, UP_AXIS, quaternionFromAxisAngle } from './rotation';
import type { ObstaclePart, RotatingObstacleConfig } from './types';
import { requireCount, requireFinite, requirePositive } from './validation';

export interface WindmillOptions extends RotatingObstacleConfig {
  bladeCount?: number;
  bladeLength?: number;
  bladeWidth?: number;
  bladeThickness?: number;
  hubRadius?: number;
  /** Static support below the hub; 0 removes it. */
  towerHeight?: number;
  towerWidth?: number;
}

export const DEFAULT_WINDMILL_AXIS: Vec3 = { x: 0, y: 0, z: 1 };

const DEFAULT_BLADE_COUNT = 4;
const DEFAULT_BLADE_LENGTH = 1.8;
const DEFAULT_BLADE_WIDTH = 0.9;
const DEFAULT_BLADE_THICKNESS = 0.18;
const DEFAULT_HUB_RADIUS = 0.28;
const DEFAULT_TOWER_HEIGHT = 1.6;
const DEFAULT_TOWER_WIDTH = 0.45;
const DEFAULT_COLOR = 0xe8b25c;
const TOWER_COLOR = 0x8d6a45;

interface WindmillSpec {
  rotating: ObstaclePart[];
  fixed: ObstaclePart[];
  bladeCount: number;
  bladeLength: number;
  bladeWidth: number;
  bladeThickness: number;
  hubRadius: number;
  towerHeight: number;
  towerWidth: number;
}

function resolveWindmill(options: WindmillOptions): WindmillSpec {
  const bladeCount = requireCount(options.bladeCount ?? DEFAULT_BLADE_COUNT, 'Windmill bladeCount', 2);
  const bladeLength = requirePositive(options.bladeLength ?? DEFAULT_BLADE_LENGTH, 'Windmill bladeLength');
  const bladeWidth = requirePositive(options.bladeWidth ?? DEFAULT_BLADE_WIDTH, 'Windmill bladeWidth');
  const bladeThickness = requirePositive(options.bladeThickness ?? DEFAULT_BLADE_THICKNESS, 'Windmill bladeThickness');
  const hubRadius = requirePositive(options.hubRadius ?? DEFAULT_HUB_RADIUS, 'Windmill hubRadius');
  const towerHeight = Math.max(0, requireFinite(options.towerHeight ?? DEFAULT_TOWER_HEIGHT, 'Windmill towerHeight'));
  const towerWidth = requirePositive(options.towerWidth ?? DEFAULT_TOWER_WIDTH, 'Windmill towerWidth');
  const bladeMaterial = new THREE.MeshStandardMaterial({
    color: options.color ?? DEFAULT_COLOR,
    roughness: 0.55,
    metalness: 0.1,
  });
  const bladeGeometry = new THREE.BoxGeometry(bladeLength, bladeThickness, bladeWidth);
  const rotating: ObstaclePart[] = [{
    id: 'hub',
    geometry: new THREE.CylinderGeometry(hubRadius, hubRadius, bladeThickness * 2.2, 14),
    material: bladeMaterial,
    halfExtents: { x: hubRadius, y: bladeThickness * 1.1, z: hubRadius },
    collider: false,
  }];

  const reach = hubRadius + bladeLength / 2;
  for (let index = 0; index < bladeCount; index += 1) {
    const angle = (TAU * index) / bladeCount;
    rotating.push({
      id: 'blade-' + index,
      geometry: bladeGeometry,
      material: bladeMaterial,
      halfExtents: { x: bladeLength / 2, y: bladeThickness / 2, z: bladeWidth / 2 },
      offset: { x: Math.cos(angle) * reach, y: 0, z: -Math.sin(angle) * reach },
      rotation: quaternionFromAxisAngle(UP_AXIS, angle),
    });
  }

  const fixed: ObstaclePart[] = [];
  if (towerHeight > 0) {
    fixed.push({
      id: 'tower',
      geometry: new THREE.BoxGeometry(towerWidth, towerHeight, towerWidth),
      material: new THREE.MeshStandardMaterial({ color: TOWER_COLOR, roughness: 0.8, metalness: 0 }),
      halfExtents: { x: towerWidth / 2, y: towerHeight / 2, z: towerWidth / 2 },
      offset: { x: 0, y: -towerHeight / 2, z: 0 },
    });
  }

  return {
    rotating,
    fixed,
    bladeCount,
    bladeLength,
    bladeWidth,
    bladeThickness,
    hubRadius,
    towerHeight,
    towerWidth,
  };
}

/**
 * Mini-golf windmill: blades spin on the kinematic pivot while the tower stays
 * still on its own fixed body, so the support never rotates into the fairway.
 * Defaults to a wheel spinning around the course axis (+Z).
 */
