import RAPIER from '@dimforge/rapier3d-compat';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import type { ObstacleBodyHandle, ObstacleBodySpec, ObstaclePhysicsAdapter } from './types';

export const OBSTACLE_COLLISION_GROUPS = collisionGroups(
  CollisionLayers.OBSTACLE,
  CollisionLayers.BALL,
);

/** Production adapter: kinematic bodies with cuboid colliders in the Rapier world. */
export class RapierObstaclePhysics implements ObstaclePhysicsAdapter {
  constructor(private readonly physics: PhysicsWorld) {}

  createBody(spec: ObstacleBodySpec): ObstacleBodyHandle {
    const kinematic = spec.kind === 'kinematic';
    const desc = kinematic
      ? RAPIER.RigidBodyDesc.kinematicPositionBased()
      : RAPIER.RigidBodyDesc.fixed();
    desc.setTranslation(spec.position.x, spec.position.y, spec.position.z);
    desc.setRotation(spec.rotation);
    const body = this.physics.world.createRigidBody(desc);

    for (const collider of spec.colliders) {
      this.physics.world.createCollider(
        RAPIER.ColliderDesc.cuboid(
          collider.halfExtents.x,
          collider.halfExtents.y,
          collider.halfExtents.z,
        )
          .setTranslation(collider.offset.x, collider.offset.y, collider.offset.z)
          .setRotation(collider.rotation)
          .setFriction(collider.friction)
          .setRestitution(collider.restitution)
          .setCollisionGroups(OBSTACLE_COLLISION_GROUPS),
        body,
      );
    }

    let removed = false;
    return {
      setNextRotation: (rotation) => {
        if (removed || !kinematic) return;
        body.setNextKinematicRotation(rotation);
      },
      dispose: () => {
        if (removed) return;
        removed = true;
        this.physics.world.removeRigidBody(body);
      },
    };
  }
}
