import type * as THREE from 'three';
import type { MovingObstacle, ObstacleDescriptor } from '../courses/types';
import { RotatingBar } from './RotatingBar';
import type { RotatingObstacle } from './RotatingObstacle';
import { Spinner } from './Spinner';
import { Windmill } from './Windmill';
import type { ObstaclePhysicsAdapter, RotatingObstacleConfig } from './types';

export interface RotatingObstacleOptions {
  scene?: THREE.Object3D;
  physics?: ObstaclePhysicsAdapter;
  friction?: number;
  restitution?: number;
  maxStepSeconds?: number;
}

export function isRotatingObstacleDescriptor(descriptor: ObstacleDescriptor): descriptor is MovingObstacle {
  return 'motion' in descriptor && descriptor.motion.kind === 'rotate';
}

/** Turns a course descriptor into a runtime obstacle, or null when it does not rotate. */
export function createRotatingObstacle(
  descriptor: ObstacleDescriptor,
  options: RotatingObstacleOptions = {},
): RotatingObstacle | null {
  if (!isRotatingObstacleDescriptor(descriptor)) return null;
  const { motion, size, transform } = descriptor;
  const config: RotatingObstacleConfig = {
    id: descriptor.id,
    position: transform.position,
    axis: motion.axis,
    speed: motion.speed,
    phase: motion.phase ?? 0,
    enabled: descriptor.enabled ?? true,
    scene: options.scene,
    physics: options.physics,
    friction: options.friction,
    restitution: options.restitution,
    maxStepSeconds: options.maxStepSeconds,
  };

  switch (descriptor.type) {
    case 'windmill':
      return new Windmill({
        ...config,
        bladeLength: size.x / 2,
        bladeWidth: size.y,
        bladeThickness: size.z,
        towerHeight: Math.max(0, transform.position.y),
      });
    case 'spinner':
      return new Spinner({
        ...config,
        armCount: 2,
        armLength: size.x / 2,
        height: size.y,
        thickness: size.z,
      });
    default:
      return new RotatingBar({ ...config, length: size.x, height: size.y, thickness: size.z });
  }
}

export function createRotatingObstacles(
  descriptors: readonly ObstacleDescriptor[],
  options: RotatingObstacleOptions = {},
): RotatingObstacle[] {
  const created: RotatingObstacle[] = [];
  for (const descriptor of descriptors) {
    const obstacle = createRotatingObstacle(descriptor, options);
    if (obstacle) created.push(obstacle);
  }
  return created;
}
