import type { ObstacleDescriptor } from '../courses/types';
import type { RotatingObstacle } from './RotatingObstacle';
import { createRotatingObstacles, type RotatingObstacleOptions } from './RotatingObstacleFactory';

/** Owns every rotating obstacle of a hole and drives them from one update call. */
export class RotatingObstacleField {
  private readonly items: RotatingObstacle[] = [];
  private disposed = false;

  static fromDescriptors(
    descriptors: readonly ObstacleDescriptor[],
    options: RotatingObstacleOptions = {},
  ): RotatingObstacleField {
    const field = new RotatingObstacleField();
    for (const obstacle of createRotatingObstacles(descriptors, options)) field.add(obstacle);
    return field;
  }

  get obstacles(): readonly RotatingObstacle[] {
    return this.items;
  }

  get size(): number {
    return this.items.length;
  }

  add<T extends RotatingObstacle>(obstacle: T): T {
    if (!this.disposed) this.items.push(obstacle);
    return obstacle;
  }

  get(id: string): RotatingObstacle | undefined {
    return this.items.find((obstacle) => obstacle.id === id);
  }

  update(deltaSeconds: number): void {
    if (this.disposed) return;
    for (const obstacle of this.items) obstacle.update(deltaSeconds);
  }

  setElapsed(seconds: number): void {
    if (this.disposed) return;
    for (const obstacle of this.items) obstacle.setElapsed(seconds);
  }

  reset(): void {
    if (this.disposed) return;
    for (const obstacle of this.items) obstacle.reset();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    for (const obstacle of this.items) obstacle.dispose();
    this.items.length = 0;
  }
}
